    ctx.rotate(this.angle);
    ctx.beginPath();
    ctx.moveTo(0, -12);
    ctx.lineTo(8, 12);
    ctx.lineTo(-8, 12);
    ctx.closePath();
    ctx.fillStyle = '#0f0';
    ctx.fill();
    ctx.restore();
  },
  accelerate() {
    this.vx += Math.cos(this.angle) * this.thrust;
    this.vy += Math.sin(this.angle) * this.thrust;
  }
};

